export const BODY: string = "\n<p>ہر کراپ کی ایک نسبت ہوتی ہے، چاہے آپ نے اسے خود چنا ہو یا نہیں۔ نسبت وہ مستطیل کی شکل ہے جسے آپ محفوظ رکھتے ہیں، اور یہی طے کرتی ہے کہ تصویر کہاں فٹ بیٹھے گی اور کیسی نظر آئے گی۔</p>\n<p>مربع کراپ اور چوڑا کراپ ایک دوسرے کی جگہ نہیں لے سکتے۔ ایک پروفائل تصویر کے لیے موزوں ہے، دوسرا بینر کے لیے، اور غلط نسبت استعمال کرنے کا مطلب ہے کہ پلیٹ فارم آپ کی جگہ خود تصویر دوبارہ کاٹ دے گا۔</p>\n<p>یہ مضمون عام نسبتوں، ہر ایک کے استعمال اور انتخاب کا طریقہ بتاتا ہے۔ اس میں اپنی مرضی کی نسبتیں، ان کے پیچھے کی ریاضی اور وہ غلطیاں بھی شامل ہیں جو نسبت نظر انداز کرنے سے پیدا ہوتی ہیں۔ نسبت سمجھنے کے بعد آپ <a href=\"/ur/tasveer-crop-karein/\">امیج کراپر</a> سے اسے چند سیکنڈ میں لگا سکتے ہیں۔</p>\n<h2 id=\"what-is-an-aspect-ratio\">نسبت کیا ہوتی ہے؟</h2>\n<p>نسبت تصویر کی چوڑائی اور اونچائی کے درمیان تعلق ہے، جو دو عددوں کے درمیان نقطوں کے ساتھ لکھی جاتی ہے، جیسے 16:9۔</p>\n<p>یہ عدد تناسب بتاتے ہیں، پکسلز کی تعداد نہیں۔ 16:9 والی تصویر 1920 بائی 1080 پکسلز بھی ہو سکتی ہے اور 1280 بائی 720 پکسلز بھی، اور دونوں کی شکل ایک جیسی ہوتی ہے۔ کسی بھی تصویر کی نسبت معلوم کرنے کے لیے چوڑائی کو اونچائی پر تقسیم کریں: 1200 پکسلز چوڑی اور 800 پکسلز اونچی تصویر کی نسبت 1.5 بنتی ہے، جو 3:2 کے برابر ہے۔</p>\n<p>نسبتیں اس لیے اہم ہیں کہ ہر منزل اپنی شکل مانگتی ہے۔ مربع چاہنے والا پلیٹ فارم چوڑی تصویر کو کاٹ دے گا، اور 4:3 چاہنے والا پرنٹر کسی اور شکل کو کھینچے گا یا تراشے گا۔</p>\n<h2 id=\"ratio-1-1\">1:1 — مربع</h2>\n<p>نسبت 1:1 کا مطلب ہے چوڑائی اور اونچائی برابر ہیں، اس لیے تصویر کامل مربع بنتی ہے۔ یہ سوشل میڈیا کی سب سے عام نسبت ہے، جو پروفائل تصویروں اور گرڈ پوسٹوں میں استعمال ہوتی ہے۔</p>\n<p>مربع متوازن اور غیر جانبدار محسوس ہوتا ہے۔ یہ پورٹریٹ، مصنوعات کی تصویروں اور ہر اس چیز کے لیے موزوں ہے جسے گرڈ میں بغیر کسی سمت کو ترجیح دیے بیٹھنا ہو۔ لیکن اکثر پلیٹ فارم مربع پروفائل تصویر کو دائرے کی شکل میں دکھاتے ہیں: آپ کے مربع کے کونے کٹ جاتے ہیں، اس لیے چہرہ فریم کے اندر اچھی طرح رکھیں۔</p>\n<p>1:1 میں کاٹتے وقت موضوع کو درمیان میں رکھیں اور سر کے اوپر تھوڑی جگہ چھوڑیں۔ اوپری کنارے کو چھونے والا چہرہ دائروی کراپ میں بال کھو دے گا، اور کونے میں رکھا موضوع مکمل طور پر کٹ جائے گا۔</p>\n<h2 id=\"ratio-4-3\">4:3 — کلاسک تصویر کی شکل</h2>\n<p>نسبت 4:3 اونچائی سے تھوڑی چوڑی ہوتی ہے۔ یہ ٹیلی ویژن اسکرینوں اور ابتدائی ڈیجیٹل کیمروں کی معیاری شکل تھی، اور روایتی تصویروں کے لیے آج بھی موزوں ہے۔</p>\n<p>یہ دستاویزات اور اسکین کیے گئے صفحات کے لیے اچھا پہلے سے طے شدہ انتخاب ہے، جہاں مواد مربع سے چوڑا ہوتا ہے مگر ویڈیو فریم جتنا چوڑا نہیں۔ یہ معیاری کاغذ پر اچھی طرح پرنٹ بھی ہوتی ہے۔ بہت سے فون کیمرے آج بھی 4:3 موڈ دیتے ہیں: اگر آپ کا کیمرا اسی نسبت میں شوٹ کرتا ہے تو 4:3 میں کاٹنے سے تقریباً پورا فریم محفوظ رہتا ہے۔</p>\n<p>4:3 اس وقت استعمال کریں جب موضوع کو تھوڑی افقی جگہ چاہیے مگر تصویر پینوراما جیسی نہ لگے۔ گروپ تصویر، کمرے کا اندرونی منظر یا دستاویز اس شکل میں اچھی لگتی ہے۔</p>\n<h2 id=\"ratio-3-2\">3:2 — کیمرے کا معیار</h2>\n<p>نسبت 3:2 پینتیس ملی میٹر فلم کیمروں سے آئی ہے، اور زیادہ تر ڈی ایس ایل آر اور مرر لیس کیمروں کی پہلے سے طے شدہ شکل اب بھی یہی ہے۔ یہ 4:3 سے چوڑی مگر 16:9 سے تنگ ہوتی ہے۔</p>\n<p>یہ مناظر اور گلیوں کی فوٹوگرافی کے لیے موزوں ہے، جہاں اضافی چوڑائی منظر کو سانس لینے کی جگہ دیتی ہے، بغیر تصویر کو پینوراما بنائے۔ پرنٹ کے سائز بھی اکثر اس نسبت سے ملتے ہیں: 6 بائی 4 انچ کا پرنٹ بالکل 3:2 ہوتا ہے، اس لیے اس شکل میں کاٹی گئی تصویر بغیر مزید تراشے پرنٹ ہو جاتی ہے۔</p>\n<p>اگر آپ کا کیمرا 3:2 میں شوٹ کرتا ہے اور آپ اکثر پرنٹ کرتے ہیں تو اپنے کراپ اسی نسبت میں رکھیں۔ آپ لیبارٹری کی طرف سے اپنی پسندیدہ تصویر کے کنارے کاٹے جانے کے حیران کن لمحے سے بچ جائیں گے۔</p>\n<h2 id=\"ratio-16-9\">16:9 — چوڑی اسکرین</h2>\n<p>نسبت 16:9 جدید اسکرینوں کی شکل ہے: ٹیلی ویژن، مانیٹر اور لینڈ اسکیپ میں فون کی اسکرین۔ یہ چوڑی اور سنیمائی ہوتی ہے، اور ایسے مواد کے لیے بنی ہے جو اسکرین بھر پھیلتا ہے۔</p>\n<p>یہ ویڈیو تھمب نیل، ویب سائٹ بینر اور پریزنٹیشن سلائیڈز کے لیے درست انتخاب ہے۔ 16:9 کراپ جگہ کو بغیر کسی طرف خالی پٹی چھوڑے بھر دیتا ہے۔ اس کی قیمت عمودی جگہ ہے: لمبی تصویر سے 16:9 کاٹنے پر اوپر اور نیچے بہت سے پکسلز ضائع ہوتے ہیں، اس لیے موضوع کو پتلی پٹی میں آرام سے بیٹھنا چاہیے۔</p>\n<p>16:9 کراپ میں اہم مواد درمیان میں رکھیں۔ پلیٹ فارم موبائل کے لیے اطراف کو اکثر دوبارہ تراشتے ہیں، اس لیے بائیں یا دائیں کنارے کے قریب کچھ بھی غائب ہو سکتا ہے۔</p>\n<h2 id=\"ratio-4-5-and-9-16\">4:5 اور 9:16 — عمودی شکلیں</h2>\n<p>عمودی نسبتیں اس لیے اہم ہیں کہ زیادہ تر لوگ مواد سیدھے پکڑے گئے فون پر دیکھتے ہیں۔ 4:5 کراپ ایک لمبا پورٹریٹ ہے جو مربع سے زیادہ فون اسکرین بھرتا ہے۔</p>\n<p>نسبت 4:5 سوشل فیڈز کی عمودی پوسٹوں کے لیے موزوں ہے۔ یہ فون پر مربع پوسٹ سے بڑی دکھائی دیتی ہے، جس سے تصویر پوری اسکرین بھرے بغیر زیادہ نمایاں ہو جاتی ہے۔ نسبت 9:16 عمودی سمت میں پورے فون کی اسکرین ہے: یہ کہانیوں، ریلز اور عمودی ویڈیو کی شکل ہے، اور اسکرین کو کنارے سے کنارے تک بھرتی ہے۔</p>\n<p>عمودی کراپ میں محتاط فریمنگ چاہیے۔ 9:16 میں دبایا گیا چوڑا منظر اپنے زیادہ تر اطراف کھو دیتا ہے، اس لیے یہ نسبت وسیع مناظر کے بجائے اکیلے موضوعات کے لیے موزوں ہے۔</p>\n<h2 id=\"custom-ratios\">اپنی مرضی کی نسبتیں: جب کوئی پہلے سے طے شدہ شکل نہ ملے</h2>\n<p>کبھی کبھی کوئی معیاری نسبت آپ کی منزل سے نہیں ملتی۔ مخصوص بینر کا سائز، کتاب کا سرورق یا پکسلز میں طے شدہ ابعاد والا فارم، سب کو اپنی شکل چاہیے۔</p>\n<p>کراپر میں آزاد موڈ آپ کو فریم کو کسی بھی شکل میں کھینچنے دیتا ہے۔ ٹول درست آؤٹ پٹ ابعاد دکھاتا ہے، اس لیے آپ مطلوبہ سائز سے بالکل مطابقت رکھ سکتے ہیں۔ اپنی مرضی کی نسبتیں بڑی تصویر سے تفصیل کاٹنے کے لیے بھی کارآمد ہیں: صفحے کا ایک پیراگراف، تصویر سے لوگو یا ہجوم میں سے چہرہ، سب ایسی شکلیں مانگتے ہیں جو پہلے سے طے شدہ سیٹنگز میں نہیں ملتیں۔</p>\n<p>اپنی مرضی کی نسبت استعمال کرتے وقت پہلے وہ پکسل ابعاد لکھ لیں جو آپ کو چاہییں۔ آنکھ سے بنایا گیا کراپ غلط ہونا آسان ہے، جبکہ عدد سے جانچا گیا کراپ درست ہوتا ہے۔</p>\n<h2 id=\"ratio-vs-resolution\">نسبت بمقابلہ ریزولوشن: دو الگ چیزیں</h2>\n<p>نسبت شکل بتاتی ہے، جبکہ ریزولوشن پکسلز میں سائز بتاتا ہے۔ دو تصویریں ایک نسبت رکھتے ہوئے بہت مختلف ریزولوشن رکھ سکتی ہیں، اور دو تصویریں ایک ریزولوشن رکھتے ہوئے مختلف نسبتیں رکھ سکتی ہیں۔</p>\n<p>500 بائی 500 پکسلز کا 1:1 کراپ اور 2000 بائی 2000 پکسلز کا 1:1 کراپ ایک ہی شکل رکھتے ہیں، مگر دوسرے میں سولہ گنا زیادہ پکسلز ہوتے ہیں۔ یہ اس لیے اہم ہے کہ 1000 پکسلز چاہنے والا پلیٹ فارم 500 پکسلز والے کراپ کو کھینچ کر دھندلا کر دے گا، چاہے شکل درست ہو: نسبت درست تھی اور ریزولوشن غلط تھا۔</p>\n<p>دونوں عدد ہمیشہ جانچیں۔ کراپر آؤٹ پٹ ابعاد دکھاتا ہے، اس لیے ڈاؤن لوڈ سے پہلے نسبت سے شکل اور پکسلز کی تعداد سے سائز کی تصدیق کریں۔</p>\n<h2 id=\"ratio-mistakes\">غلط نسبت سے پیدا ہونے والی غلطیاں</h2>\n<p>سب سے عام غلطی ایک نسبت میں کاٹنا اور پھر نتیجے کو دوسری شکل میں فٹ کرنے کے لیے کھینچنا ہے۔ کھینچنا چہروں اور چیزوں کو بگاڑ دیتا ہے، اور نقصان فوراً نظر آتا ہے۔</p>\n<p>دوسری غلطی پلیٹ فارم کو اپنی تصویر دوبارہ کاٹنے دینا ہے۔ بینر کے طور پر اپ لوڈ کی گئی مربع تصویر کو پلیٹ فارم کاٹ دے گا، اور وہ خود طے کرے گا کہ کیا کاٹنا ہے، آپ نہیں۔ لوگ یہ بھی بھول جاتے ہیں کہ نسبت بدلنے سے پکسلز ضائع ہوتے ہیں: چوڑی تصویر کو مربع میں کاٹنے سے بایاں اور دایاں تیسرا حصہ ختم ہو جاتا ہے، جس میں موضوع ہو سکتا ہے۔</p>\n<p>حل یہ ہے کہ کاٹنے سے پہلے منزل کے اصولوں سے نسبت چنیں۔ پلیٹ فارم کی سائز گائیڈ کی پانچ سیکنڈ کی جانچ تینوں غلطیوں سے بچا لیتی ہے۔</p>\n<h2 id=\"ratio-for-print\">پرنٹ کے لیے نسبتیں</h2>\n<p>پرنٹ کے سائز کی اپنی نسبتیں ہوتی ہیں، اور وہ ہمیشہ اسکرین کی شکلوں سے نہیں ملتیں۔ 6 بائی 4 انچ کا پرنٹ 3:2 ہے، 10 بائی 8 انچ کا پرنٹ 5:4 ہے، اور A4 صفحہ تقریباً 1.41:1 ہے۔</p>\n<p>پرنٹ کرنے سے پہلے کاغذ کے سائز کی نسبت جانچیں اور اس سے مطابقت کے لیے کاٹیں۔ 16:9 میں کاٹی گئی تصویر 4:3 پرنٹ پر سفید پٹیاں چھوڑ دے گی، یا پرنٹر کی تراش سے اپنے کنارے کھو دے گی۔ پرنٹ کو صرف شکل نہیں، ریزولوشن بھی چاہیے: چھوٹا کراپ بڑا پرنٹ کرنے پر نرم نظر آئے گا، اس لیے نسبت کے ساتھ پکسلز کی تعداد بھی تصدیق کریں۔</p>\n<p>شک ہو تو پرنٹ سائز سے تھوڑا بڑا کاٹیں اور لیبارٹری کو اضافی حصہ تراشنے دیں۔ تھوڑا اضافی حاشیہ بالکل غلط شکل والے کراپ سے زیادہ محفوظ ہوتا ہے۔</p>\n<h2 id=\"ratio-workflow\">نسبت منتخب کرنے کا عملی طریقہ</h2>\n<p>ہر اس جگہ کی فہرست بنانے سے شروع کریں جہاں تصویر نظر آئے گی۔ جس تصویر کو پروفائل تصویر، بینر اور پرنٹ بننا ہو، اسے ایک ہی اصل سے تین مختلف کراپ چاہییں۔</p>\n<p>ہر نسخہ اصل فائل سے الگ کاٹیں۔ کراپ کا کراپ معیار کھو دیتا ہے، جبکہ اصل سے تازہ کراپ تیز رہتے ہیں۔ ہر فائل کا نام اس کی منزل اور نسبت پر رکھیں، جیسے avatar-1x1.png یا banner-16x9.png: واضح نام آپ کو غلط شکل غلط جگہ اپ لوڈ کرنے سے روکتے ہیں۔</p>\n<p>اصل فائل محفوظ رکھیں۔ منزلیں اپنے سائز کے اصول بدلتی رہتی ہیں، اور محفوظ اصل آپ کو خراب نقل سے شروع کیے بغیر نئی نسبت میں دوبارہ کاٹنے دیتا ہے۔</p>\n<h2 id=\"ratio-cheat-sheet\">نسبتوں کی فوری یاد دہانی</h2>\n<p>پروفائل تصویروں، گرڈ پوسٹوں اور مربع یا دائرے میں دکھائی جانے والی ہر چیز کے لیے 1:1 استعمال کریں۔ موضوع کو سر کے اوپر جگہ کے ساتھ درمیان میں رکھیں۔</p>\n<p>روایتی تصویروں، دستاویزات اور معیاری کاغذ پر پرنٹ کے لیے 4:3 استعمال کریں۔ یہ سب سے محفوظ عام تصویر کی شکل ہے۔ 6 بائی 4 انچ پر پرنٹ کرنے والے کیمرا تصویروں کے لیے 3:2 استعمال کریں: یہ فلم کے معیار اور زیادہ تر ڈی ایس ایل آر کے آؤٹ پٹ سے ملتی ہے۔</p>\n<p>بینر، تھمب نیل اور سلائیڈز کے لیے 16:9 استعمال کریں۔ اہم مواد درمیان میں رکھیں، ان کناروں سے دور جنہیں موبائل اسکرینیں تراشتی ہیں۔</p>\n<h2 id=\"ratio-for-video-thumbnails\">ویڈیو تھمب نیل کے لیے نسبتیں</h2>\n<p>ویڈیو تھمب نیل تقریباً ہمیشہ 16:9 ہوتے ہیں، کیونکہ وہ وائیڈ اسکرین شکل والے ویڈیو پلیئرز پر بیٹھتے ہیں۔ کسی اور نسبت میں کاٹا گیا تھمب نیل پلیٹ فارم کھینچے گا یا اس کے گرد پٹیاں دکھائے گا۔</p>\n<p>تھمب نیل کراپ میں چہرہ اور مرکزی موضوع بڑا رکھیں۔ تھمب نیل فیڈ میں چھوٹا دکھائی دیتا ہے، اس لیے چھوٹا موضوع غائب ہو جاتا ہے اور بڑا توجہ کھینچتا ہے۔ اگر تھمب نیل پر عنوان لگانے کا ارادہ ہے تو متن کے لیے جگہ چھوڑیں: ایک طرف موضوع اور دوسری طرف خالی جگہ والا 16:9 کراپ متن کو بیٹھنے کی جگہ دیتا ہے۔</p>\n<p>شائع کرنے سے پہلے تھمب نیل فون پر جانچیں۔ ڈیسک ٹاپ پر ٹھیک لگنے والا کراپ چھوٹی اسکرین پر ناقابلِ خواندگی ہو سکتا ہے، جہاں تھمب نیل صرف چند سینٹی میٹر چوڑا ہوتا ہے۔</p>\n<h2 id=\"ratio-for-ecommerce\">ای کامرس اور مصنوعات کی فہرستوں کے لیے نسبتیں</h2>\n<p>مصنوعات کی فہرستیں عام طور پر مربع تصویریں مانگتی ہیں، کیونکہ مربعوں کا گرڈ صاف ستھرا لگتا ہے اور پیشہ ورانہ نظر آتا ہے۔ زیادہ تر دکانوں کے لیے 1:1 کراپ سب سے محفوظ انتخاب ہے۔</p>\n<p>کچھ بازار مخصوص نسبت مانگتے ہیں، جیسے 4:3 یا 3:2، اور اگر تصویر نہ ملے تو وہ اسے خود کاٹ دیں گے۔ کاٹنے سے پہلے فہرست کے اصول جانچیں، بعد میں نہیں۔ مصنوعات کے گرڈ میں تخلیق سے زیادہ مستقل مزاجی اہم ہے: ہر مصنوعات کو ایک ہی نسبت اور ایک جیسے حاشیوں کے ساتھ کاٹیں، تاکہ کیٹلاگ صاف اور قابلِ اعتماد لگے۔</p>\n<p>مصنوعات کے صفحے کی مرکزی تصویر کے لیے 16:9 یا 3:2 جیسی چوڑی نسبت بہتر کام کرتی ہے۔ یہ مصنوعات کو سیاق میں دکھاتی ہے، اور ارد گرد طرزِ زندگی کی پس منظر کی جگہ دیتی ہے۔</p>\n<h2 id=\"ratio-and-composition\">نسبت اور ترکیب: شکل احساس کیسے بدلتی ہے</h2>\n<p>مربع پرسکون اور متوازن محسوس ہوتا ہے، کیونکہ کوئی سمت غالب نہیں آتی۔ یہ پورٹریٹ، ساکت زندگی اور ہر اس چیز کے لیے موزوں ہے جسے مرکوز اور مستحکم محسوس ہونا چاہیے۔</p>\n<p>چوڑی نسبت کھلی اور سنیمائی محسوس ہوتی ہے، کیونکہ آنکھ فریم بھر سفر کرتی ہے۔ یہ مناظر، شہری مناظر اور ہر اس منظر کے لیے موزوں ہے جہاں چوڑائی ہی اصل بات ہو۔ اونچی نسبت قریبی اور مرکوز محسوس ہوتی ہے، کیونکہ آنکھ تنگ فریم میں اوپر نیچے جاتی ہے: یہ اکیلے موضوعات، جیسے شخص، عمارت یا درخت، کے لیے موزوں ہے۔</p>\n<p>نسبت منزل کے ساتھ ساتھ احساس کے لیے بھی چنیں۔ مربع میں کاٹا گیا منظر اپنی وسعت کا احساس کھو دیتا ہے، جبکہ چوڑا کاٹا گیا پورٹریٹ اپنی قربت کا احساس کھو دیتا ہے۔</p>\n<h2 id=\"ratio-changes-over-time\">نسبتیں بدلتی رہتی ہیں: پلیٹ فارم کے ساتھ ہم آہنگ کیسے رہیں</h2>\n<p>پلیٹ فارم کے سائز کے اصول باقاعدگی سے بدلتے ہیں، اور گزشتہ سال کام کرنے والی نسبت اس سال فٹ نہ بیٹھے۔ مربع چاہنے والا فیڈ اب عمودی پورٹریٹ کو ترجیح دے سکتا ہے، اور بینر کی جگہ کا نیا سائز ہو سکتا ہے۔</p>\n<p>ہر اہم تصویر کی اصل فائل محفوظ رکھیں۔ جب پلیٹ فارم اصول بدلے تو آپ پرانے کراپ کو کھینچنے کے بجائے اصل کو نئی نسبت میں دوبارہ کاٹ سکتے ہیں۔ ہر پلیٹ فارم کے لیے کاٹنے سے پہلے اس کی سائز گائیڈ جانچیں: دو منٹ کی جانچ اس کراپ سے بچا لیتی ہے جسے پلیٹ فارم آپ کی جگہ بری طرح دوبارہ کاٹے گا۔</p>\n<p>ان نسبتوں کی مختصر فہرست بنائیں جو آپ سب سے زیادہ استعمال کرتے ہیں، اور جب پلیٹ فارم بدلے تو اسے اپ ڈیٹ کریں۔ میز پر رکھا نوٹ جس پر لکھا ہو پروفائل 1:1، بینر 16:9، کہانی 9:16، ہر کاٹنے کے سیشن میں وقت بچاتا ہے۔</p>\n<p>فون فیڈ میں نمایاں ہونے والی عمودی پوسٹوں کے لیے 4:5 اور مکمل اسکرین کہانیوں اور عمودی ویڈیو کے لیے 9:16 استعمال کریں۔ عملی مراحل کے لیے <a href=\"/ur/blog/tasveer-kaise-crop-karein/\">تصویر کیسے کاٹیں</a> دیکھیں، اور مکمل جائزے کے لیے <a href=\"/ur/blog/tasveer-crop-karein-rehnumai/\">امیج کراپر: مکمل رہنما</a> پڑھیں۔ اگر تصویر کو کاٹنے کے بجائے مکمل سائز بدلنا ہو تو <a href=\"/ur/tasveer-resize-karein/\">امیج ری سائزر</a> استعمال کریں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"کراپ میں 1:1 کا کیا مطلب ہے؟","answer":"اس کا مطلب ہے چوڑائی اور اونچائی برابر ہیں، اس لیے کراپ کامل مربع بنتا ہے۔ 1:1 کراپ پروفائل تصویروں اور گرڈ پوسٹوں کے لیے موزوں ہے۔ موضوع کو سر کے اوپر جگہ کے ساتھ درمیان میں رکھیں، کیونکہ بہت سے پلیٹ فارم مربعوں کو دائرے کی شکل میں دکھاتے ہیں اور کونے کاٹ دیتے ہیں۔"},{"question":"یوٹیوب تھمب نیل کے لیے کون سی نسبت استعمال کروں؟","answer":"16:9 استعمال کریں، جو معیاری وائیڈ اسکرین شکل ہے اور 1280 بائی 720 پکسلز والے تھمب نیل کے سائز سے ملتی ہے۔ مرکزی موضوع اور کوئی بھی متن درمیان میں رکھیں، کیونکہ چھوٹی اسکرینوں پر کنارے تراشے جا سکتے ہیں۔"},{"question":"کیا میں تصویر کو اس نسبت میں کاٹ سکتا ہوں جس میں میرا کیمرا شوٹ نہیں کرتا؟","answer":"جی ہاں۔ نئی نسبت میں کاٹنے سے کناروں سے پکسلز ہٹ جاتے ہیں جب تک شکل نہ مل جائے۔ چوڑی تصویر مربع بن سکتی ہے اور مربع چوڑا بینر بن سکتا ہے، بشرطیکہ محفوظ علاقہ منزل کے لیے کافی بڑا ہو۔"},{"question":"تصویر پرنٹ کرنے کے لیے کون سی نسبت استعمال کروں؟","answer":"کاغذ کے سائز سے مطابقت رکھیں: 6 بائی 4 انچ پرنٹ کے لیے 3:2، 10 بائی 8 انچ پرنٹ کے لیے 5:4، اور A4 کے لیے تقریباً 1.41:1۔ نسبت اور پکسلز کی تعداد دونوں جانچیں، کیونکہ چھوٹا کراپ بڑا پرنٹ کرنے پر نرم نظر آئے گا۔"},{"question":"انسٹاگرام اپ لوڈ کے بعد میری تصویر دوبارہ کیوں کاٹتا ہے؟","answer":"انسٹاگرام ان تصویروں کو دوبارہ کاٹتا ہے جو اس کی منتخب جگہ کی پسندیدہ نسبتوں سے نہیں ملتیں۔ اپ لوڈ سے پہلے درست نسبت میں کاٹیں، جیسے گرڈ پوسٹ کے لیے 1:1 یا عمودی پوسٹ کے لیے 4:5، اور فریمنگ آپ کے اختیار میں رہے گی۔"},{"question":"نسبت اور ریزولوشن میں کیا فرق ہے؟","answer":"نسبت تصویر کی شکل ہے، جیسے 16:9، جبکہ ریزولوشن پکسلز میں سائز ہے، جیسے 1920 بائی 1080۔ دو تصویریں ایک نسبت رکھتے ہوئے مختلف ریزولوشن رکھ سکتی ہیں۔ اپ لوڈ یا پرنٹ سے پہلے دونوں ہمیشہ جانچیں۔"}];
